namespace NovaHarvest.Core.Dialogue;public sealed class Dialogue {readonly Dictionary<string,DialogueNode> _nodes=new();public string Id{get;}public string StartNodeId{get;}public DialogueNode? CurrentNode{get;private set;}public bool IsFinished=>CurrentNode?.IsEnd??false;public Dialogue(string id,string start){Id=id;StartNodeId=start;}public bool AddNode(DialogueNode n){if(n is null||string.IsNullOrWhiteSpace(n.Id)||_nodes.ContainsKey(n.Id))return false;_nodes.Add(n.Id,n);return true;}public bool Start(){if(!_nodes.TryGetValue(StartNodeId,out var n))return false;CurrentNode=n;return true;}public bool Continue()=>CurrentNode is not null&&!string.IsNullOrWhiteSpace(CurrentNode.NextNodeId)&&MoveTo(CurrentNode.NextNodeId);public bool Choose(string id){var c=CurrentNode?.Choices.FirstOrDefault(x=>x.Id==id);return c is not null&&MoveTo(c.NextNodeId);}bool MoveTo(string id)=>_nodes.TryGetValue(id,out var n)&&(CurrentNode=n)!=null;}
